    </div>
    <div class="days" id="calendarDays"></div>
  </div>

  <div class="time-slots">
    <h3>اختر وقتًا مناسبًا</h3>
    <div class="slots-list" id="slotsList">
      <button class="slot-btn disabled">٩:٠٠ ص - محجوز</button>
      <button class="slot-btn">٩:٣٠ ص</button>
      <button class="slot-btn">١٠:٠٠ ص</button>
