    </div>
  </div>

  <button class="confirm-btn" id="confirmBtn">تأكيد الحجز</button>

  <script>
    const today = new Date();
    let currentMonth = today.getMonth();
    let currentYear = today.getFullYear();

    const monthNames = [
      "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
      "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
    ];

    const daysInMonth = (year, month) => new Date(year, month + 1, 0).getDate();
    const firstDayOfMonth = (year, month) => new Date(year, month, 1).getDay();

    // Adjust so week starts on Saturday (6)
    function getStartDayIndex(year, month) {
      const d = firstDayOfMonth(year, month);
      // Shift so Saturday = 0
      return (d + 1) % 7;
    }

    function renderCalendar() {
      const daysContainer = document.getElementById("calendarDays");
      const monthYearLabel = document.getElementById("monthYear");
      monthYearLabel.textContent = `${monthNames[currentMonth]} ${currentYear}`;

      daysContainer.innerHTML = "";

      const startDay = getStartDayIndex(currentYear, currentMonth);
      const totalDays = daysInMonth(currentYear, currentMonth);

      // Empty cells before first day
      for (let i = 0; i < startDay; i++) {
        const empty = document.createElement("div");
        empty.className = "day empty";
        daysContainer.appendChild(empty);
      }

      // Day cells
      for (let day = 1; day <= totalDays; day++) {
        const dayEl = document.createElement("div");
        dayEl.className = "day";
        dayEl.textContent = day;

        const isToday =
          day === today.getDate() &&
          currentMonth === today.getMonth() &&
          currentYear === today.getFullYear();

        if (isToday) {
          dayEl.classList.add("today");
        }

        dayEl.addEventListener("click", () => {
          document.querySelectorAll(".day").forEach(d => d.classList.remove("selected"));
          dayEl.classList.add("selected");
        });

        daysContainer.appendChild(dayEl);
      }
    }

    document.getElementById("prevMonth").addEventListener("click", () => {
      currentMonth--;
      if (currentMonth < 0) {
        currentMonth = 11;
        currentYear--;
      }
      renderCalendar();
    });

    document.getElementById("nextMonth").addEventListener("click", () => {
      currentMonth++;
      if (currentMonth > 11) {
        currentMonth = 0;
        currentYear++;
      }
      renderCalendar();
    });

    document.getElementById("prevMonthCal").addEventListener("click", () => {
      currentMonth--;
      if (currentMonth < 0) {
        currentMonth = 11;
        currentYear--;
      }
      renderCalendar();
    });

